+            }
+            
+            table.setX1(minX);
+            table.setY1(minY);
+            table.setX2(maxX);
+            table.setY2(minY);
+            table.setX3(maxX);
+            table.setY3(maxY);
+            table.setX4(minX);
+            table.setY4(maxY);
