+
+    private String chr;
+    private Float x;
+    private Float y;
+    private Float width;
+    private Float height;
+    private Integer pageIndex;
+
+    public CharData() {
+    }
+
+    /**
+     * Constructor for assigning the character data from TextPosition
+     */
+    public CharData(TextPosition position, Integer pageIndex) {
+        this.chr = position.getUnicode();
+        this.x = position.getXDirAdj();
+        this.y = position.getYDirAdj();
+        this.width = position.getWidthDirAdj();
+        this.height = position.getHeightDir();
+        this.pageIndex = pageIndex;
+    }
+
+    public String getChr() {
+        return chr;
+    }
+
+    public String setChr(String chr) {
+        this.chr = chr;
+        return chr;
+    }
+
+    public Float getX() {
+        return x;
+    }
+
+    public void setX(Float x) {
+        this.x = x;
+    }
+
+    public Float getY() {
+        return y;
+    }
+
+    public void setY(Float y) {
+        this.y = y;
+    }
+
+    public Float getWidth() {
+        return width;
+    }
+
+    public void setWidth(Float width) {
+        this.width = width;
+    }
+
+    public Float getHeight() {
+        return height;
+    }
+
